template <typename UnionPtrType>
FramePtr Frame::Clone() const {
  switch (tag_) {
    case Tag::kV1:
      return NewV1(
          mojo::Clone(*data_.v1));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, Frame>::value>::type*>
bool Frame::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kV1:
      return mojo::Equals(*(data_.v1), *(other.data_.v1));
  }

  return false;
}
template <typename UnionPtrType>
V1FramePtr V1Frame::Clone() const {
  switch (tag_) {
    case Tag::kIntroduction:
      return NewIntroduction(
          mojo::Clone(*data_.introduction));
    case Tag::kConnectionResponse:
      return NewConnectionResponse(
          mojo::Clone(*data_.connection_response));
    case Tag::kPairedKeyEncryption:
      return NewPairedKeyEncryption(
          mojo::Clone(*data_.paired_key_encryption));
    case Tag::kPairedKeyResult:
      return NewPairedKeyResult(
          mojo::Clone(*data_.paired_key_result));
    case Tag::kCertificateInfo:
      return NewCertificateInfo(
          mojo::Clone(*data_.certificate_info));
    case Tag::kCancelFrame:
      return NewCancelFrame(
          mojo::Clone(*data_.cancel_frame));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, V1Frame>::value>::type*>
bool V1Frame::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kIntroduction:
      return mojo::Equals(*(data_.introduction), *(other.data_.introduction));
    case Tag::kConnectionResponse:
      return mojo::Equals(*(data_.connection_response), *(other.data_.connection_response));
    case Tag::kPairedKeyEncryption:
      return mojo::Equals(*(data_.paired_key_encryption), *(other.data_.paired_key_encryption));
    case Tag::kPairedKeyResult:
      return mojo::Equals(*(data_.paired_key_result), *(other.data_.paired_key_result));
    case Tag::kCertificateInfo:
      return mojo::Equals(*(data_.certificate_info), *(other.data_.certificate_info));
    case Tag::kCancelFrame:
      return mojo::Equals(*(data_.cancel_frame), *(other.data_.cancel_frame));
  }

  return false;
}
